from h_balanced import *
def report():
 v=json.loads((R/'validation-summary.json').read_text());sel=json.loads((R/'selection.json').read_text());audit=json.loads((R/'audit.json').read_text());diag=json.loads((R/'dev-diagnostics.json').read_text());counts=json.loads((R/'pre-training-counts.json').read_text())
 sec=sum(json.loads((R/f'{p}-summary.json').read_text())['wall_seconds'] for p in ('pilot','train','dev'));trainsec=sum(json.loads((R/f'learning-{a}-{s}.json').read_text())['wall_seconds'] for a in ('A','B') for s in SEEDS)
 lines=['# 両席抽出によるH方策蒸留：固定A/B対照','', '公開HとFrozen gen3を変更せず、元gen3からpolicy MLPだけを教師Hの着手分布へ蒸留した。実終局報酬による追加強化学習ではない。旧失敗/gateは163791fのまま保存。','',f'今回の事前gate: **{sel["gate"]}**。全3seed・epoch8固定、seed選別なし。固定3seedの推論であり、任意の更新seedへの一般化は未証明。確認試験はgate通過時のみ。','', '## 対照と経験量','', 'Aは実手番0のみ、Bは各段階で実手番0/1を32/32。共通256生成ゲーム/seedから各段階64適格ペアを採用し、各arm192ラベル/seed・8epoch・96Adam更新。両armの元ゲーム/段階ペアは同じ。前回の約364–369ラベル/seedとは総量が異なるため、旧失敗との直接的な因果差分にはしない。今回の主対照は同量のA/Bである。候補0/1・未完成教師・欠損片側はペアごと除外。','', '開発用は別96ゲーム/seedから各段階16ペアの両席、96ラベル/seed。1ゲーム複数局面は独立標本扱いしない。Bの半数はAに対して隣接する1ply後で、同段階でも局面内容の差は不可避。全seedで外生乱数列を共有するがモデルにより軌跡は異なる。A/Bラベルは半分重複。','', '教師は固定gen3/H幅4完成6ply。60秒は固定木完走の安全上限。全対象値を真のWDL/minimax値とは呼ばない。trunk/value/position/priorは凍結。元のAdam1e-4/CE+.05KL/batch16を保持。','', '## 新validation（勝1・引分0.5のpoint）','', '各行12新prefix×先後×3seed=72局。同一prefix内6局をまとめてbootstrap。B/publicとB/Aを事前の2主比較familyとしてBonferroni補正。A/public・単体は参考値。過去72局を合算しない。','', '|比較|point|通常95%CI|2比較補正CI|平均ゲーム得点差 (95%CI)|','|---|---:|---|---|---|']
 lines[lines.index('## 新validation（勝1・引分0.5のpoint）'):lines.index('## 新validation（勝1・引分0.5のpoint）')]=['## 実際の採用元ゲーム数','']+[f'- seed{s}: A/B共通のユニーク元ゲーム{c["unique_games"]["A"]}件（B={c["unique_games"]["B"]}）、段階別適格ペア '+str({k:v for k,v in c['train'].items() if k in ('12','20','28')}) for s,c in counts.items()]+['']
 def ci(x):return f'{x[0]*100:.2f}–{x[1]*100:.2f}%'
 for m,r in v.items():lines.append(f'|{m}|{r["point"]*100:.2f}%|{ci(r["point_ci95"])}|{ci(r["point_ci_bonferroni2"])}|{r["difference"]:+.3f} [{r["difference_ci95"][0]:+.3f},{r["difference_ci95"][1]:+.3f}]|')
 lines+=['','### seed差・席差（記述統計）','']
 for m,r in v.items():
  lines.append(f'- {m}: seed '+', '.join(f'{s}={x["point"]*100:.2f}% ({x["difference"]:+.2f})' for s,x in r['by_seed'].items())+'; 席 '+', '.join(f'{s}={x["point"]*100:.2f}%' for s,x in r['by_seat'].items()))
 lines+=['','## 実時間・完了率','', '|比較/側|平均ms|p99ms|maxms|500ms超過/手数|6ply完成率(非pass)|非pass fallback|','|---|---:|---:|---:|---|---:|---:|']
 for m,r in v.items():
  if m.startswith('policy'):continue
  for side,t in r['time'].items():lines.append(f'|{m}/{side}|{t["mean_ms"]:.2f}|{t["p99_ms"]:.2f}|{t["max_ms"]:.2f}|{t["over500"]}/{t["moves"]}|{t["depth6_fraction"]*100:.1f}%|{t["nonpass_fallback"]}|')
 lines+=['','両者500ms上限、実wall一致ではない。forcedpassは元statsでfallback=Trueになるため非pass失敗と分けた。単体とHは異なる計算量。各act内cacheはreset、各試合初回も計測に含む。初回モデルロードは対局wallに含めない。','', '## 両席dev診断','', '|arm/seed|教師一致 before→after|greedy変更|教師選択top4脱落|top4重複|','|---|---|---:|---:|---:|']
 for k,d in diag.items():lines.append(f'|{k}|{d["original_agreement"]*100:.2f}→{d["agreement"]*100:.2f}%|{d["greedy_change"]*100:.2f}%|{d["teacher_chosen_dropped_top4"]}/{d["labels"]}|{d["top4_overlap"]*100:.2f}%|')
 lines+=['', '非policy tensorはbit一致。CPU/CUDAそれぞれのdevice内で更新前後のvalueがbit一致（CPUとCUDA相互のbit一致を意味しない）。教師一致率だけで強化成功とは判定しない。席偏りが旧失敗の主因だったとは未証明。教師幅4の候補範囲と凍結valueの誤差を再生産する限界がある。更新したpolicyはrootだけでなく探索内部の候補選別も変えるため、root教師一致の改善が固定木の改善と同じではない。','', '## 費用・検証','',f'pilot+新データ生成wall {sec:.2f}秒、6学習run cache/update/metrics/save {trainsec:.2f}秒、合計{(sec+trainsec)/60:.2f}分（90分枠内）。監査・対戦wallは別。生成はCPU、policy更新はCUDA float32。8epoch/96steps perarm/seed、計576updates。学習・対戦・監査は重ねない。','',f'監査: {audit["coordinate_generation_games"]}生成対局と評価全対局の独立座標合法性/終局得点、全教師ラベル合法性/tie/score整合、{audit["label_tree_replays"]}固定木再生、訓練分離、モデルSHA、集計再計算PASS。以前の原訓練indexはSHA参照、巨大履歴複製なし。新visited状態と評価前後の分離はaudit.json。別processCUDA12updates vs5+save/load+7でhead/Adam/NumPy/Torch/CUDA RNG一致。','', '## 判断と限界','']
 if not sel['gate']:lines+=['事前gate未達のため独立確認は実行していない。今回のvalidationだけで一般的優越・同等性・人間への強さを主張しない。本番Hを上回る候補として採用しない。席抽出の修正は実装上妥当でも、それが棋力向上を保証するとはいえない。小さな蒸留条件の救済探索はここで止める。','', '次の仮説は、固定または管理された探索後の実ゲーム終局WDLでpolicy/valueを更新し、探索葉と学習分布のずれを検証すること。教師手一致ではなく勝敗へ直接接続し、非探索対照/探索付き同予算の両方を比較する必要がある。これは今回未実施で、効果は未証明。']
 else:lines+=['独立確認結果はconfirmation-summary.jsonを参照。採用判断は2主比較の補正CIと得点差を分ける。現時点で本番適用は行わない。']
 lines+=['','人間棋譜は今回取得/利用しておらず、人間の敗因を再現したとはいわない。main/Web/Frozenは変更なし。推論export A/Bは研究名で保存し履歴sidecar不要。','', '## 再現','', '```bash','export OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1','python scripts/h_balanced.py pilot --games 4','python scripts/h_balanced.py train --games 256','python scripts/h_balanced.py dev --games 96','python scripts/h_balanced.py prepare','python scripts/h_balanced_train.py','python scripts/h_balanced_eval.py','python scripts/audit_h_balanced.py','python scripts/report_h_balanced.py','python scripts/play_h_distill.py --checkpoint artifacts/h-distill-balanced/B-1751401.pt --model-seed 1751401 --search --human-seat 0','```','', '生成は既存出力を上書きしない。再実行時は別worktree/出力パスを使う。元gen3 3ファイルと旧訓練indexをmodels.json/pre-evaluation-separation.jsonのSHAで照合。通常CPU推論にはindex不要。CUDA学習PyTorch2.7.1+cu128、GPU RTX5090、CPU thread1。']
 (R/'REPORT.md').write_text('\n'.join(lines)+'\n')
